from lib import *
S = SS('l60')
steps = [
    step("源仓库:300 个提交,每次改 40 个 20 KB 随机二进制文件之一,共 300 个 blob,pack 里 1200 个对象(300 commit + 600 tree + 300 blob)、5.83 MiB。服务端要允许过滤:git config uploadpack.allowFilter true(输出 true)。", t=tl(S(1)), mark=lidx(S(1), 'in-pack: 1200', 'size-pack: 5.83 MiB'), done=lidx(S(1), 'true'), kv=KV([['对象', '300 commit + 600 tree + 300 blob'], ['大小', '5.83 MiB'], ['服务端', 'uploadpack.allowFilter=true']], ['服务端'])),
    step("几种克隆(file://,--no-checkout):完整 1,200 个对象、5932 KB;--filter=blob:none 900 个对象(commit + tree)、67 KB——blob 一个都没下载,体积只有完整的 1.1%;--filter=blob:limit=1k 同样是 900 个、67 KB(这里每个 blob 都有 20 KB,没有一个小于 1k);--filter=tree:0 更狠,只有 300 个对象(只有 commit)、37 KB,连 tree 也要用到时才取。", t=tl(S(2)), mark=lidx(S(2), '--filter=blob:none', '--filter=tree:0'), done=lidx(S(2), '完整', '--filter=blob:limit=1k'), b=bars([['完整', 5932, '5932 KB'], ['blob:none', 67, '67 KB'], ['blob:limit=1k', 67, '67 KB'], ['tree:0', 37, '37 KB']], 5932, mark=[1, 3], done=[0, 2]), kv=KV([['blob:none', '不要任何 blob'], ['blob:limit=n', '只要小于 n 的 blob'], ['tree:0', '连 tree 也不要']], ['blob:none'])),
    step("blob:none 克隆留下的记号:配置里 remote.origin.promisor = true 和 remote.origin.partialclonefilter = blob:none(这个远程是“承诺者”:缺失的对象可以向它要);pack 目录里除了 .idx/.pack/.rev 还有 .promisor 文件。git rev-list --objects --missing=print HEAD 里有 300 个以 ? 开头的行(缺失的对象,就是 300 个 blob);非缺失的对象 900 个(commit 加 tree)。", t=tl(S(3)), mark=lidx(S(3), 'remote.origin.promisor true', 'partialclonefilter', '.promisor'), done=lidx(S(3), '  300', '900'), kv=KV([['promisor', '缺失的对象可以向这个远程要'], ['.promisor 文件', '标记这个 pack 是承诺 pack'], ['--missing=print', '以 ? 列出缺失的对象']], ['promisor'])),
    step("按需下载:访问一个缺失的 blob(git cat-file -s <sha>)时,git 在后台启动 git -c fetch.negotiationAlgorithm=noop fetch origin --no-tags --no-write-fetch-head --recurse-submodules=no --filter=blob:none --stdin,再通过 upload-pack 把这一个 blob 取回来。对象数 900 → 901。用户感觉不到,只是第一次访问慢一点。", t=tl(S(4)), mark=lidx(S(4), 'git fetch origin --no-tags', 'git upload-pack', '901'), done=lidx(S(4), 'git cat-file -s'), kv=KV([['缺失的对象被访问', '后台 git fetch --stdin'], ['只取这一个', '下载 1 个 blob'], ['需要服务端', 'allowAnySHA1InWant']], ['后台 git fetch --stdin'])),
    step("git checkout 需要当前文件的 blob:一次批量 fetch 把 HEAD 的 40 个文件的 blob 都取回来,对象数 940(900 + 39,有一个上一步已经取过)。而 git log -p 要历史上所有 blob 的补丁:剩下的 260 个 blob 被触发了 260 次后台 fetch——每个 blob 一次,完成后对象数回到 1200,缺失的对象数 0。批量访问历史内容的命令在 partial clone 里可能比完整克隆慢得多。", t=tl(S(5)), mark=lidx(S(5), '260 次后台 fetch', '现在还缺失的对象数: 0'), done=lidx(S(5), 'checkout 之后对象数 940'), b=bars([['git checkout', 1, '1 次批量 fetch(39 个 blob)'], ['git log -p', 260, '260 次逐个 fetch']], 260, mark=[1], done=[0]), kv=KV([['checkout', '一次批量取全部需要的 blob'], ['log -p', '逐个 blob 触发 fetch'], ['建议', '需要历史内容时先 fetch 或用完整克隆']], ['log -p'])),
]
A = mkarti('l60', 60, 'Git,partial clone,--filter,promisor,按需下载,真实验证,动画演示',
    '实测部分克隆:300 个 20 KB blob 的仓库完整克隆 1,200 个对象 5932 KB,--filter=blob:none 只有 900 个对象 67 KB,tree:0 只有 300 个对象 37 KB;配置里 remote.origin.promisor 与 .promisor 文件标记承诺者;访问缺失的 blob 时后台 git fetch --stdin 取回;checkout 一次批量取 39 个 blob,git log -p 触发 260 次逐个 fetch。',
    '部分克隆(--filter=blob:none)让你先拿到完整历史的结构、需要某个文件内容时再按需下载。这篇看它省了多少、留下什么记号、缺失的对象是怎么被悄悄取回的,以及哪些操作会触发大量逐个 fetch。',
    [('67 vs 5932 KB', 'blob:none 克隆与完整克隆的对象库大小(1.1%)'), ('1 次 vs 260 次', 'checkout 批量取 blob 的 fetch 次数,与 git log -p 逐个取的次数'), ('.promisor', 'pack 目录里标记承诺 pack 的文件,与 remote.origin.promisor 配置一起使用')],
    [('过滤', '<p><code>--filter=blob:none</code> 不下载任何 blob,<code>blob:limit=n</code> 只下载小于 n 的,<code>tree:0</code> 连 tree 也不要。服务端需要 <code>uploadpack.allowFilter=true</code>。</p>'),
     ('承诺者', '<p>克隆时 git 把远程标成 promisor(<code>remote.origin.promisor=true</code>,记录过滤规则),拿到的 pack 带 <code>.promisor</code> 文件。对象库里缺失的对象因此“有来处”:需要时可以向它要。<code>git rev-list --objects --missing=print</code> 用 <code>?</code> 列出缺失的对象。</p>'),
     ('按需下载', '<p>任何需要缺失 blob 的操作(<code>cat-file</code>、<code>checkout</code>、<code>diff</code>、<code>log -p</code>)都会在后台启动 <code>git fetch --filter=blob:none --stdin</code> 把需要的对象取回。用户感觉不到,只是第一次访问慢一点。</p>'),
     ('批量与逐个', '<p>checkout 一次知道需要哪些 blob,批量 fetch(本例 39 个);<code>git log -p</code> 沿着历史一个个访问,每个缺失的 blob 触发一次 fetch(本例 260 次)。批量扫描历史的命令在 partial clone 里可能比完整克隆慢得多。</p>'),
     ('什么时候用', '<p>仓库里有很多大文件、历史很长,而你只需要最新版本和结构时,partial clone 能把克隆缩小到约 1%。如果需要全部历史内容,还是完整克隆更省事。</p>')],
    steps,
    [ENV_I_GIT + '。源仓库是脚本生成的 300 个提交(40 个 20 KB 的随机二进制文件轮流修改);服务端是本机的 file:// 路径,配置 uploadpack.allowFilter 与 allowAnySHA1InWant;对象数 = count + in-pack;“260 次后台 fetch”来自 GIT_TRACE 里 run_command: git … fetch 的行数',
     '没有验证:真实的 HTTP 服务器(GitHub 等)上 partial clone 的行为与限制;--filter=sparse:oid;partial clone 与 sparse-checkout 结合(见 sparse-checkout 一篇);fetch.negotiationAlgorithm=noop 的含义;部分克隆之后 git gc 对缺失对象的处理;promisor 远程不可达时的报错'],
    '部分克隆')
